ALTER TABLE `ts_analyses` ADD COLUMN `configuration_hash` binary(32) GENERATED ALWAYS AS (unhex(sha2(concat_ws(' ',sha2(`repository_id`,256),sha2(`tool_id`,256),sha2(`ref`,256),sha2(`analysis_category`,256)),256))) STORED, ADD COLUMN `unique_most_recent` tinyint(1) GENERATED ALWAYS AS (if(`most_recent`,1,NULL)) VIRTUAL, ADD UNIQUE KEY `idx_analyses_most_recent` (`configuration_hash`,`unique_most_recent`);
